import Breadcrumbs from '@jetbrains/ring-ui-built/components/breadcrumbs/breadcrumbs'
import type {EntryPointProps} from 'react-relay'
import {useFragment, graphql, usePreloadedQuery} from 'react-relay'
import {useParams} from 'react-router'

import {useRunningBuildUpdaterRelay} from '../../../../../hooks/relay/useRunningBuildUpdaterRelay'
import {useBuildStatusIconRelay} from '../../../../../hooks/useBuildStatusIcon'
import useFormatBuildNumber from '../../../../../hooks/useFormatBuildNumber'
import {getPipelineHref, getProjectHref} from '../../../../../routes'
import {useDisplayDate} from '../../../../../utils/dateTimeUtils'
import BreadcrumbsLink from '../../../../common/Breadcrumbs/BreadcrumbsLink/BreadcrumbsLink'
import BreadcrumbsDropdown from '../../../../common/BreadcrumbsDropdown/BreadcrumbsDropdown'
import {usePipelineNameOrDraft} from '../../EditPipelinePage/EditPipelinePage.hooks'
import {usePipelineId} from '../../hooks/pipeline'
import usePipelineDocumentTitle from '../../hooks/usePipelineDocumentTitle'
import {getAccountRootProjectId} from '../../PipelinesPages.consts'
import {isPipelinesEnabledInExclusiveMode} from '../../utils/featureToggles'

import type {PipelinesBreadcrumbsPipelineFragment$key} from './__generated__/PipelinesBreadcrumbsPipelineFragment.graphql'
import type {PipelinesBreadcrumbsQuery} from './__generated__/PipelinesBreadcrumbsQuery.graphql'
import type {PipelinesBreadcrumbsRunFragment$key} from './__generated__/PipelinesBreadcrumbsRunFragment.graphql'
import {query} from './PipelinesBreadcrumbs.queries'

const pipelineFragment = graphql`
  fragment PipelinesBreadcrumbsPipelineFragment on PipelineRest {
    id
    name
    parentProject {
      id
      name
      ancestorProjects {
        project {
          id
          name
        }
      }
    }
  }
`

const pipelineRunFragment = graphql`
  fragment PipelinesBreadcrumbsRunFragment on Build {
    ...useBuildStatusIconFragment
    ...useFormatBuildNumberFragment
    ...useRunningBuildUpdaterRelayFragment
    state
    startDate
  }
`

type ExtraProps = {
  isEditMode?: boolean
  isPipelineRun?: boolean
}

type Queries = {
  main: PipelinesBreadcrumbsQuery
}

export default function PipelinesBreadcrumbs({
  queries,
  extraProps: {isEditMode, isPipelineRun},
}: EntryPointProps<Queries, {}, {}, ExtraProps>) {
  const pipelineId = usePipelineId()
  const {pipelineRunId = ''} = useParams()

  const {pipeline: pipelineKey, build: pipelineRunKey} = usePreloadedQuery(query, queries.main)
  const pipeline = useFragment<PipelinesBreadcrumbsPipelineFragment$key>(
    pipelineFragment,
    pipelineKey ?? null,
  )
  const pipelineName = pipeline?.name ?? ''
  const parentProject = pipeline?.parentProject
  const projects = parentProject?.ancestorProjects?.project || []
  const isShowParentProject =
    !isPipelinesEnabledInExclusiveMode() && parentProject?.id != null && parentProject.name != null

  const build = useFragment<PipelinesBreadcrumbsRunFragment$key>(
    pipelineRunFragment,
    pipelineRunKey ?? null,
  )
  const runNumber = useFormatBuildNumber(build)
  const isQueued = build?.state === 'queued'
  const runStatusIcon = useBuildStatusIconRelay(build, true)
  const startDate = useDisplayDate(build?.startDate, true)
  useRunningBuildUpdaterRelay(build)

  const pipelineDraftName = usePipelineNameOrDraft() ?? ''

  usePipelineDocumentTitle(isEditMode ? `Edit ${pipelineDraftName}` : pipelineName)

  return (
    <Breadcrumbs>
      {!isPipelinesEnabledInExclusiveMode() &&
        projects.map(
          ({name, id}) =>
            id != null &&
            id !== getAccountRootProjectId() &&
            name != null && (
              <span key={id}>
                <BreadcrumbsLink to={getProjectHref(id)} name={name} />
                <BreadcrumbsDropdown projectId={id} isEditMode={isEditMode} />
              </span>
            ),
        )}
      {isShowParentProject && (
        <span>
          <BreadcrumbsLink to={getProjectHref(parentProject.id)} name={parentProject.name} />
          <BreadcrumbsDropdown projectId={parentProject.id} isEditMode={isEditMode} />
        </span>
      )}
      {(!isPipelinesEnabledInExclusiveMode() || isPipelineRun) && (
        <span>
          <BreadcrumbsLink
            active={!isPipelineRun}
            to={isPipelineRun ? getPipelineHref(pipelineId) : undefined}
            name={isEditMode ? pipelineDraftName : pipelineName}
            leftIcon={isEditMode ? 'settings' : 'pipeline'}
          />
          {!isPipelinesEnabledInExclusiveMode() && pipelineId && (
            <BreadcrumbsDropdown pipelineId={pipelineId} isEditMode={isEditMode} />
          )}
        </span>
      )}
      {isPipelineRun && (
        <BreadcrumbsLink
          active
          to={getPipelineHref(pipelineId, pipelineRunId)}
          name={
            isQueued ? 'In queue' : `Run ${runNumber}${startDate != null ? ` on ${startDate}` : ''}`
          }
          leftIcon={runStatusIcon}
        />
      )}
    </Breadcrumbs>
  )
}
export type PipelinesBreadcrumbsComponent = typeof PipelinesBreadcrumbs
